1	//! Port of `tests/test18.cpp`: exercises `SortedMap` keyed on a two-element tuple.
2	//!
3	//! Output is byte-for-byte identical to the C++ original for every argument vector,
4	//! including the ones `std::atoi` merely tolerates.
5	
6	mod compat;
7	mod sortedcontainers;
8	
9	use self::compat::{atoi, ostream_bool};
10	use self::sortedcontainers::{update, SortedMap};
11	
12	/// The original keys on `std::tuple<int, int>`; a Rust tuple orders lexicographically the
13	/// same way, so the iteration order carries over unchanged.
14	type Key = (i32, i32);
15	
16	fn main() {
17	    let mut n: i32 = 18;
18	    // `argv[1]`, parsed the way `std::atoi` would. `args_os` rather than `args` because the
19	    // C++ program accepts arbitrary bytes here while `args` panics on non-UTF-8 input; the
20	    // lossy decoding is equivalent for `atoi`, which stops at the first byte that is not a
21	    // digit either way.
22	    if let Some(argument) = std::env::args_os().nth(1) {
23	        n = atoi(&argument.to_string_lossy());
24	    }
25	
26	    let mut m: SortedMap<Key, String> = SortedMap::new();
27	    for i in 0..n {
28	        m.insert((i, i * 2), format!("value_{}", i));
29	    }
30	
31	    println!("{}", m.len());
32	
33	    let test_key1: Key = (3, 6);
34	    let test_key2: Key = (5, 10);
35	
36	    println!("{}", ostream_bool(m.contains_key(&test_key1)));
37	    println!("{}", ostream_bool(m.contains_key(&test_key2)));
38	
39	    // `m[test_key1]` on a missing key inserts an empty string and returns it, so this both
40	    // prints a blank line and grows the map — which the `keys()` count below reflects.
41	    println!("{}", m.entry_or_default(test_key1));
42	
43	    *m.entry_or_default(test_key1) = String::from("modified");
44	    println!("{}", m.entry_or_default(test_key1));
45	
46	    let keys = m.keys();
47	    let values = m.values();
48	
49	    println!("{}", keys.len());
50	    println!("{}", values.len());
51	
52	    for i in 0..4 {
53	        m.remove(&(i, i * 2));
54	    }
55	
56	    println!("{}", m.len());
57	
58	    // Each of the next three lines is printed only when the lookup lands on an entry, so
59	    // the total number of output lines varies with `n`.
60	    if let Some(value) = m.find(&(6, 12)).value() {
61	        println!("{}", value);
62	    }
63	
64	    if let Some(key) = m.lower_bound(&(7, 14)).key() {
65	        println!("{}", key.0);
66	    }
67	
68	    if let Some(key) = m.upper_bound(&(7, 14)).key() {
69	        println!("{}", key.0);
70	    }
71	
72	    let mut m2: SortedMap<Key, String> = SortedMap::new();
73	    for i in 0..n / 2 {
74	        m2.insert((i + 10, (i + 10) * 2), format!("other_{}", i));
75	    }
76	
77	    update(&mut m, &m2);
78	
79	    println!("{}", m.len());
80	    println!("{}", ostream_bool(m.contains_key(&(12, 24))));
81	
82	    let (first, last) = m.equal_range(&(8, 16));
83	    let mut cursor = first;
84	    let mut count = 0;
85	    while cursor != last {
86	        count += 1;
87	        cursor.advance();
88	    }
89	    println!("{}", count);
90	
91	    let fallback = String::from("default");
92	    println!("{}", m.get_or(&(100, 200), &fallback));
93	
94	    m.clear();
95	
96	    println!("{}", m.len());
97	    println!("{}", ostream_bool(m.is_empty()));
98	}
