1	//! C and C++ runtime behaviours the port has to reproduce byte for byte.
2	//!
3	//! Rust's equivalents of these are deliberately stricter than C's, so the differences are
4	//! observable and the originals have to be spelled out.
5	
6	/// `std::atoi` on a decimal string, including its edge cases.
7	///
8	/// `str::parse::<i32>()` is not a substitute: it rejects everything `atoi` shrugs off.
9	/// `atoi` skips leading whitespace, takes an optional sign, consumes as many decimal digits
10	/// as it finds, and stops at the first byte that is not one — yielding `0` when there were no
11	/// digits at all. So `"  12"`, `"+5"`, `"7abc"`, `"12.9"` and `"1e3"` parse to 12, 5, 7, 12
12	/// and 1, while `"abc"`, `"0x10"` and `""` all parse to 0.
13	///
14	/// Out-of-range input matters too, because glibc implements `atoi(s)` as
15	/// `(int)strtol(s, nullptr, 10)`: the magnitude saturates at `LONG_MAX`/`LONG_MIN` and is
16	/// then truncated to 32 bits. That is why `"2147483648"` comes out as `-2147483648`,
17	/// `"4294967296"` as `0`, `"9999999999999999999999"` as `-1`, and its negation as `0`.
18	pub fn atoi(text: &str) -> i32 {
19	    let bytes = text.as_bytes();
20	    let mut index = 0;
21	
22	    while index < bytes.len() && is_space(bytes[index]) {
23	        index += 1;
24	    }
25	
26	    let negative = match bytes.get(index) {
27	        Some(b'-') => {
28	            index += 1;
29	            true
30	        }
31	        Some(b'+') => {
32	            index += 1;
33	            false
34	        }
35	        _ => false,
36	    };
37	
38	    // Accumulate the magnitude, clamping at the limit `strtol` would report for this sign.
39	    let limit: u64 = if negative {
40	        1u64 << 63 // -(i64::MIN) does not fit in an i64, but its magnitude fits here.
41	    } else {
42	        i64::MAX as u64
43	    };
44	    let mut magnitude: u64 = 0;
45	    while let Some(digit) = bytes.get(index).and_then(|byte| decimal_digit(*byte)) {
46	        magnitude = magnitude
47	            .checked_mul(10)
48	            .and_then(|scaled| scaled.checked_add(digit))
49	            .filter(|candidate| *candidate <= limit)
50	            .unwrap_or(limit);
51	        index += 1;
52	    }
53	
54	    // `magnitude as i64` maps the negative clamp 2^63 onto `i64::MIN`, whose negation
55	    // wraps back to itself — exactly what the C cast chain produces.
56	    let wide = magnitude as i64;
57	    let value = if negative { wide.wrapping_neg() } else { wide };
58	    value as i32
59	}
60	
61	/// The bytes C's `isspace` accepts in the default locale.
62	fn is_space(byte: u8) -> bool {
63	    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
64	}
65	
66	fn decimal_digit(byte: u8) -> Option<u64> {
67	    match byte {
68	        b'0'..=b'9' => Some(u64::from(byte - b'0')),
69	        _ => None,
70	    }
71	}
72	
73	/// How `std::cout << bool` renders: `1` or `0`, never `true` or `false`.
74	pub fn ostream_bool(value: bool) -> u8 {
75	    u8::from(value)
76	}
77	
78	#[cfg(test)]
79	mod tests {
80	    use super::*;
81	
82	    #[test]
83	    fn plain_numbers() {
84	        assert_eq!(atoi("0"), 0);
85	        assert_eq!(atoi("18"), 18);
86	        assert_eq!(atoi("007"), 7);
87	        assert_eq!(atoi("+5"), 5);
88	        assert_eq!(atoi("-5"), -5);
89	        assert_eq!(atoi("-0"), 0);
90	        assert_eq!(atoi("2147483647"), i32::MAX);
91	        assert_eq!(atoi("-2147483648"), i32::MIN);
92	    }
93	
94	    #[test]
95	    fn leading_whitespace_is_skipped() {
96	        assert_eq!(atoi(" 12"), 12);
97	        assert_eq!(atoi("\t9"), 9);
98	        assert_eq!(atoi("\n\r\u{b}\u{c} 3"), 3);
99	        assert_eq!(atoi("  -3"), -3);
100	    }
101	
102	    #[test]
103	    fn parsing_stops_at_the_first_non_digit() {
104	        assert_eq!(atoi("7abc"), 7);
105	        assert_eq!(atoi("12.9"), 12);
106	        assert_eq!(atoi("1e3"), 1);
107	        assert_eq!(atoi("5 "), 5);
108	        assert_eq!(atoi("0x10"), 0);
109	    }
110	
111	    #[test]
112	    fn input_without_digits_is_zero() {
113	        assert_eq!(atoi(""), 0);
114	        assert_eq!(atoi("abc"), 0);
115	        assert_eq!(atoi("."), 0);
116	        assert_eq!(atoi("+-3"), 0);
117	        assert_eq!(atoi("-"), 0);
118	        assert_eq!(atoi("   "), 0);
119	        // Non-UTF-8 bytes reach us as U+FFFD, which is not a digit — the same stop that
120	        // C's atoi makes on a byte above 0x7f.
121	        assert_eq!(atoi("\u{fffd}5"), 0);
122	    }
123	
124	    #[test]
125	    fn out_of_range_input_saturates_then_truncates() {
126	        assert_eq!(atoi("2147483648"), -2147483648);
127	        assert_eq!(atoi("4294967296"), 0);
128	        assert_eq!(atoi("9223372036854775807"), -1); // i64::MAX truncated
129	        assert_eq!(atoi("9999999999999999999999"), -1); // clamped to i64::MAX, then truncated
130	        assert_eq!(atoi("-9999999999999999999999"), 0); // clamped to i64::MIN, then truncated
131	        assert_eq!(atoi("-9223372036854775808"), 0);
132	        // Long digit runs must clamp rather than wrap around u64.
133	        assert_eq!(atoi(&"9".repeat(100)), -1);
134	        assert_eq!(atoi(&format!("-{}", "9".repeat(100))), 0);
135	        assert_eq!(atoi(&format!("{}5", "0".repeat(100))), 5);
136	    }
137	
138	    #[test]
139	    fn bools_render_as_digits() {
140	        assert_eq!(ostream_bool(true).to_string(), "1");
141	        assert_eq!(ostream_bool(false).to_string(), "0");
142	    }
143	}
