1	//! Two-level bucket storage: the engine behind [`SortedMap`](super::SortedMap).
2	//!
3	//! Entries live in a `Vec` of buckets, each bucket a `Vec<(K, V)>` kept in ascending
4	//! key order, and the buckets themselves ordered relative to one another. Locating a
5	//! key is a binary search over bucket tails followed by a binary search inside the
6	//! chosen bucket, so lookups stay `O(log n)` while insertion and removal only shift
7	//! elements within one bucket instead of across the whole collection.
8	//!
9	//! Two invariants hold at all times and everything else depends on them:
10	//!
11	//! 1. No bucket is ever empty. An empty bucket would make the "compare against the
12	//!    bucket's last key" binary search ill-defined and would let two different
13	//!    [`Pos`] values name the same element.
14	//! 2. Every bucket's keys are strictly less than the next bucket's keys.
15	
16	/// Target bucket size. Buckets are split once they exceed twice this and merged with
17	/// a neighbour once they fall below half of it, so sizes stay within a constant factor.
18	pub const DEFAULT_LOAD_FACTOR: usize = 512;
19	
20	/// A cursor position, i.e. a C++ iterator.
21	///
22	/// A position is *normalised*: either it addresses a live element
23	/// (`bucket < buckets.len()` and `offset < buckets[bucket].len()`), or it is the
24	/// past-the-end position `bucket == buckets.len(), offset == 0`. Because empty
25	/// buckets cannot exist, each element has exactly one representation, which is what
26	/// makes comparing two positions for equality meaningful.
27	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
28	pub struct Pos {
29	    pub bucket: usize,
30	    pub offset: usize,
31	}
32	
33	pub struct Buckets<K, V> {
34	    buckets: Vec<Vec<(K, V)>>,
35	    len: usize,
36	    load: usize,
37	}
38	
39	impl<K: Ord, V> Buckets<K, V> {
40	    pub fn new(load: usize) -> Self {
41	        Buckets {
42	            buckets: Vec::new(),
43	            len: 0,
44	            load: if load == 0 { 1 } else { load },
45	        }
46	    }
47	
48	    pub fn len(&self) -> usize {
49	        self.len
50	    }
51	
52	    pub fn is_empty(&self) -> bool {
53	        self.len == 0
54	    }
55	
56	    pub fn clear(&mut self) {
57	        self.buckets.clear();
58	        self.len = 0;
59	    }
60	
61	    /// The past-the-end position, i.e. `end()`.
62	    pub fn end(&self) -> Pos {
63	        Pos {
64	            bucket: self.buckets.len(),
65	            offset: 0,
66	        }
67	    }
68	
69	    /// The entry at `pos`, or `None` when `pos` is past the end.
70	    pub fn at(&self, pos: Pos) -> Option<(&K, &V)> {
71	        self.buckets
72	            .get(pos.bucket)
73	            .and_then(|bucket| bucket.get(pos.offset))
74	            .map(|entry| (&entry.0, &entry.1))
75	    }
76	
77	    /// The position after `pos`, normalised. Advancing the end position is a no-op.
78	    pub fn advance(&self, pos: Pos) -> Pos {
79	        match self.buckets.get(pos.bucket) {
80	            None => pos,
81	            Some(bucket) => {
82	                let offset = pos.offset + 1;
83	                if offset < bucket.len() {
84	                    Pos {
85	                        bucket: pos.bucket,
86	                        offset,
87	                    }
88	                } else {
89	                    Pos {
90	                        bucket: pos.bucket + 1,
91	                        offset: 0,
92	                    }
93	                }
94	            }
95	        }
96	    }
97	
98	    /// First position whose key is `>= key`.
99	    pub fn lower_bound(&self, key: &K) -> Pos {
100	        // The first bucket that can still hold such a key is the first whose last key
101	        // is `>= key`; every earlier bucket ends below `key` and so lies entirely below it.
102	        let bucket = self
103	            .buckets
104	            .partition_point(|bucket| bucket.last().map_or(true, |entry| entry.0 < *key));
105	        if bucket == self.buckets.len() {
106	            return self.end();
107	        }
108	        let offset = self.buckets[bucket].partition_point(|entry| entry.0 < *key);
109	        Pos { bucket, offset }
110	    }
111	
112	    /// First position whose key is `> key`.
113	    pub fn upper_bound(&self, key: &K) -> Pos {
114	        let bucket = self
115	            .buckets
116	            .partition_point(|bucket| bucket.last().map_or(true, |entry| entry.0 <= *key));
117	        if bucket == self.buckets.len() {
118	            return self.end();
119	        }
120	        let offset = self.buckets[bucket].partition_point(|entry| entry.0 <= *key);
121	        Pos { bucket, offset }
122	    }
123	
124	    /// Position of `key`, or the end position when it is absent.
125	    pub fn find(&self, key: &K) -> Pos {
126	        let pos = self.lower_bound(key);
127	        match self.at(pos) {
128	            Some((found, _)) if *found == *key => pos,
129	            _ => self.end(),
130	        }
131	    }
132	
133	    pub fn get(&self, key: &K) -> Option<&V> {
134	        let pos = self.lower_bound(key);
135	        match self.at(pos) {
136	            Some((found, value)) if *found == *key => Some(value),
137	            _ => None,
138	        }
139	    }
140	
141	    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
142	        let pos = self.lower_bound(key);
143	        if self.matches(pos, key) {
144	            Some(&mut self.buckets[pos.bucket][pos.offset].1)
145	        } else {
146	            None
147	        }
148	    }
149	
150	    /// Stores `value` under `key`, returning the value it displaced, if any.
151	    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
152	        let pos = self.lower_bound(&key);
153	        if self.matches(pos, &key) {
154	            let slot = &mut self.buckets[pos.bucket][pos.offset].1;
155	            return Some(std::mem::replace(slot, value));
156	        }
157	        self.insert_at(pos, key, value);
158	        None
159	    }
160	
161	    /// The value under `key`, inserting `make()` first when the key is absent.
162	    ///
163	    /// This is the C++ `operator[]`: reading a missing key materialises it.
164	    pub fn get_or_insert_with<F: FnOnce() -> V>(&mut self, key: K, make: F) -> &mut V {
165	        let pos = self.lower_bound(&key);
166	        let pos = if self.matches(pos, &key) {
167	            pos
168	        } else {
169	            self.insert_at(pos, key, make())
170	        };
171	        &mut self.buckets[pos.bucket][pos.offset].1
172	    }
173	
174	    /// Removes `key`, returning its value when it was present.
175	    pub fn remove(&mut self, key: &K) -> Option<V> {
176	        let pos = self.lower_bound(key);
177	        if !self.matches(pos, key) {
178	            return None;
179	        }
180	        let (_, value) = self.buckets[pos.bucket].remove(pos.offset);
181	        self.len -= 1;
182	        self.rebalance(pos.bucket);
183	        Some(value)
184	    }
185	
186	    pub fn iter<'a>(&'a self) -> impl Iterator<Item = (&'a K, &'a V)> + 'a {
187	        self.buckets
188	            .iter()
189	            .flat_map(|bucket| bucket.iter())
190	            .map(|entry| (&entry.0, &entry.1))
191	    }
192	
193	    /// Whether `pos` addresses an entry keyed exactly by `key`.
194	    fn matches(&self, pos: Pos, key: &K) -> bool {
195	        match self.at(pos) {
196	            Some((found, _)) => *found == *key,
197	            None => false,
198	        }
199	    }
200	
201	    /// Inserts a new entry at `pos`, which must be `lower_bound(&key)`, and reports where
202	    /// the entry ended up once any resulting split has been applied.
203	    fn insert_at(&mut self, pos: Pos, key: K, value: V) -> Pos {
204	        self.len += 1;
205	        if self.buckets.is_empty() {
206	            self.buckets.push(vec![(key, value)]);
207	            return Pos {
208	                bucket: 0,
209	                offset: 0,
210	            };
211	        }
212	        if pos.bucket == self.buckets.len() {
213	            // The key sorts after every entry, so it belongs at the tail of the last bucket.
214	            let bucket = self.buckets.len() - 1;
215	            let offset = self.buckets[bucket].len();
216	            self.buckets[bucket].push((key, value));
217	            return self.split_if_needed(bucket, offset);
218	        }
219	        self.buckets[pos.bucket].insert(pos.offset, (key, value));
220	        self.split_if_needed(pos.bucket, pos.offset)
221	    }
222	
223	    /// Halves `bucket` if it has outgrown the load factor, translating `offset` into the
224	    /// position it occupies afterwards.
225	    fn split_if_needed(&mut self, bucket: usize, offset: usize) -> Pos {
226	        if self.buckets[bucket].len() > self.load * 2 {
227	            let mid = self.buckets[bucket].len() / 2;
228	            let tail = self.buckets[bucket].split_off(mid);
229	            self.buckets.insert(bucket + 1, tail);
230	            if offset >= mid {
231	                return Pos {
232	                    bucket: bucket + 1,
233	                    offset: offset - mid,
234	                };
235	            }
236	        }
237	        Pos { bucket, offset }
238	    }
239	
240	    /// Restores the "no empty buckets, no runt buckets" invariant after a removal.
241	    fn rebalance(&mut self, bucket: usize) {
242	        if self.buckets[bucket].is_empty() {
243	            self.buckets.remove(bucket);
244	            return;
245	        }
246	        if self.buckets.len() < 2 || self.buckets[bucket].len() >= self.load / 2 {
247	            return;
248	        }
249	        // Fold the runt into its left neighbour (or, for the first bucket, fold the right
250	        // neighbour into it) so that key order across buckets is preserved either way.
251	        let target = if bucket > 0 { bucket - 1 } else { bucket };
252	        let donor = self.buckets.remove(target + 1);
253	        self.buckets[target].extend(donor);
254	        self.split_if_needed(target, 0);
255	    }
256	}
