1	//! Cursors, the Rust stand-in for the C++ container's iterators.
2	//!
3	//! The original code treats an iterator as a comparable handle into the map:
4	//!
5	//! ```cpp
6	//! auto it = m.find(key);
7	//! if (it != m.end()) { use(it->second); }
8	//! for (auto it = range.first; it != range.second; ++it) { ... }
9	//! ```
10	//!
11	//! [`Cursor`] keeps that shape — it compares with `==`/`!=`, steps with
12	//! [`advance`](Cursor::advance), and reads through [`key`](Cursor::key) /
13	//! [`value`](Cursor::value) — while making the past-the-end case unrepresentable as a
14	//! read: dereferencing the end cursor yields `None` instead of undefined behaviour.
15	
16	use super::buckets::{Buckets, Pos};
17	
18	pub struct Cursor<'a, K, V> {
19	    store: &'a Buckets<K, V>,
20	    pos: Pos,
21	}
22	
23	impl<'a, K: Ord, V> Cursor<'a, K, V> {
24	    pub(crate) fn new(store: &'a Buckets<K, V>, pos: Pos) -> Self {
25	        Cursor { store, pos }
26	    }
27	
28	    /// Whether this is the past-the-end cursor, i.e. `it == m.end()`.
29	    pub fn is_end(&self) -> bool {
30	        self.store.at(self.pos).is_none()
31	    }
32	
33	    /// The key under the cursor, or `None` at the end. Mirrors `it->first`.
34	    pub fn key(&self) -> Option<&'a K> {
35	        self.store.at(self.pos).map(|(key, _)| key)
36	    }
37	
38	    /// The value under the cursor, or `None` at the end. Mirrors `it->second`.
39	    pub fn value(&self) -> Option<&'a V> {
40	        self.store.at(self.pos).map(|(_, value)| value)
41	    }
42	
43	    /// Both halves at once. Mirrors `*it`.
44	    pub fn entry(&self) -> Option<(&'a K, &'a V)> {
45	        self.store.at(self.pos)
46	    }
47	
48	    /// Steps to the next entry. Mirrors `++it`, except that advancing the end cursor
49	    /// leaves it at the end rather than running off the container.
50	    pub fn advance(&mut self) {
51	        self.pos = self.store.advance(self.pos);
52	    }
53	}
54	
55	// The following impls are written out by hand rather than derived: deriving would
56	// demand `K: Clone`/`K: PartialEq` and friends from the element types, when a cursor is
57	// only ever a borrow plus a position.
58	
59	impl<'a, K, V> Clone for Cursor<'a, K, V> {
60	    fn clone(&self) -> Self {
61	        *self
62	    }
63	}
64	
65	impl<'a, K, V> Copy for Cursor<'a, K, V> {}
66	
67	impl<'a, K, V> PartialEq for Cursor<'a, K, V> {
68	    /// Cursors are equal when they point at the same slot of the same map. Positions are
69	    /// normalised, so equal slots always compare equal; cursors into different maps never do.
70	    fn eq(&self, other: &Self) -> bool {
71	        std::ptr::eq(self.store, other.store) && self.pos == other.pos
72	    }
73	}
74	
75	impl<'a, K, V> Eq for Cursor<'a, K, V> {}
76	
77	impl<'a, K, V> std::fmt::Debug for Cursor<'a, K, V> {
78	    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
79	        f.debug_struct("Cursor")
80	            .field("bucket", &self.pos.bucket)
81	            .field("offset", &self.pos.offset)
82	            .finish()
83	    }
84	}
